// Process ALL orders and extract ALL employees
const allOrders = $input.all();
const employeeNotifications = [];

for (const order of allOrders) {
  const orderData = order.json;

  // Skip if no employee names in both fields
  const glassEmployee = orderData.glass?.trim();
  const materialEmployee = orderData['Material ']?.trim();

  if (!glassEmployee && !materialEmployee) {
    console.log(`⚠️  Order ${orderData['Order ID']} has no employees assigned - SKIPPING`);
    continue;
  }

  // Extract glass employee
  if (glassEmployee && glassEmployee !== '') {
    employeeNotifications.push({
      json: {
        employeeName: glassEmployee,
        employeeRole: 'glass',
        orderName: orderData.Name,
        orderContactNumber: orderData['Contact Number'],
        orderAddress: orderData.Address,
        orderID: orderData['Order ID'],
        orderDate: orderData['Order Date'],
        orderQty: orderData['Total \nQTY'],
        orderMaterial: orderData['Material\n (uPVC/Aluminium)'],
        orderSize: orderData['Quotation Size']
      }
    });
  }

  // Extract Material employee
  if (materialEmployee && materialEmployee !== '') {
    employeeNotifications.push({
      json: {
        employeeName: materialEmployee,
        employeeRole: 'material',
        orderName: orderData.Name,
        orderContactNumber: orderData['Contact Number'],
        orderAddress: orderData.Address,
        orderID: orderData['Order ID'],
        orderDate: orderData['Order Date'],
        orderQty: orderData['Total \nQTY'],
        orderMaterial: orderData['Material\n (uPVC/Aluminium)'],
        orderSize: orderData['Quotation Size']
      }
    });
  }
}

console.log(`✅ Extracted ${employeeNotifications.length} employee notifications from ${allOrders.length} orders`);
return employeeNotifications;

// ==========================================
// INDIAN MOBILE NUMBER FORMATTER & VALIDATOR
// ==========================================
// Based on Indian phone number standards:
// - Must be 10 digits long
// - Must start with 6, 7, 8, or 9
// - Format: 919876543210 (91 + 10 digits)
// ==========================================

const rawPhone = $json.Phone || '';

console.log(`📱 Processing phone: "${rawPhone}"`);

// STEP 1: Remove all spaces, hyphens, dots, parentheses
let cleaned = rawPhone.toString().replace(/[\s\-\.\(\)]/g, '');
console.log(`   Step 1 - Removed spaces/symbols: "${cleaned}"`);

// STEP 2: Remove plus sign if present
cleaned = cleaned.replace(/^\+/, '');
console.log(`   Step 2 - Removed plus sign: "${cleaned}"`);

// STEP 3: Remove leading zeros (common in local format)
cleaned = cleaned.replace(/^0+/, '');
console.log(`   Step 3 - Removed leading zeros: "${cleaned}"`);

// STEP 4: Extract only digits (remove any remaining non-numeric chars)
cleaned = cleaned.replace(/\D/g, '');
console.log(`   Step 4 - Only digits: "${cleaned}"`);

// STEP 5: Handle country code variations
if (cleaned.startsWith('91') && cleaned.length === 12) {
  // Already has 91 prefix with 10 digit number
  cleaned = cleaned;
  console.log(`   Step 5 - Already has 91 prefix: "${cleaned}"`);
} else if (cleaned.length === 10) {
  // Just 10 digit number, needs 91 prefix
  cleaned = '91' + cleaned;
  console.log(`   Step 5 - Added 91 prefix: "${cleaned}"`);
} else if (cleaned.length > 12 && cleaned.startsWith('91')) {
  // Has 91 but too many digits, take last 10 digits after 91
  cleaned = '91' + cleaned.slice(-10);
  console.log(`   Step 5 - Trimmed to 91 + last 10 digits: "${cleaned}"`);
} else if (cleaned.length > 10) {
  // More than 10 but no 91, take last 10 digits
  cleaned = '91' + cleaned.slice(-10);
  console.log(`   Step 5 - Took last 10 digits + added 91: "${cleaned}"`);
}

// STEP 6: Final validation
const isValid = cleaned.length === 12 && 
                cleaned.startsWith('91') && 
                /^91[6-9]\d{9}$/.test(cleaned);

if (!isValid) {
  console.error(`❌ INVALID: "${rawPhone}" → "${cleaned}"`);

  // Detailed error message
  let errorMsg = '';
  if (cleaned.length !== 12) {
    errorMsg = `Wrong length: ${cleaned.length} digits (expected 12)`;
  } else if (!cleaned.startsWith('91')) {
    errorMsg = 'Does not start with country code 91';
  } else if (!/^91[6-9]/.test(cleaned)) {
    errorMsg = `Invalid start digit: ${cleaned.charAt(2)} (must be 6, 7, 8, or 9)`;
  } else {
    errorMsg = 'Invalid format';
  }

  return [{
    json: {
      ...$json,
      formattedPhone: null,
      isValid: false,
      errorMessage: `Invalid phone number: ${errorMsg}`,
      originalPhone: rawPhone
    }
  }];
}

console.log(`✅ VALID: "${rawPhone}" → "${cleaned}"`);

return [{
  json: {
    ...$json,
    formattedPhone: cleaned,
    isValid: true,
    originalPhone: rawPhone
  }
}];

